class Solution {
    unordered_map<int,int> idx;

    TreeNode* build(const vector<int>& post, int& postIdx, int inStart, int inEnd) {
        if (inStart > inEnd) return nullptr;
        int rootVal = post[postIdx--];
        TreeNode* root = new TreeNode(rootVal);
        int mid = idx[rootVal];
        root->right = build(post, postIdx, mid + 1, inEnd);
        root->left  = build(post, postIdx, inStart, mid - 1);
        return root;
    }
public:
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        idx.clear();
        for (int i = 0; i < (int)inorder.size(); i++)
            idx[inorder[i]] = i;
        int postIdx = (int)postorder.size() - 1;
        return build(postorder, postIdx, 0, (int)inorder.size() - 1);
    }
};
